message.content:
{
  "avaliacoes": [
    {
      "criterio": "aderencia_curricular",
      "nota": 1,
      "justificativa": "O plano foca na identificação e explicação de casos base e recursivos em algoritmos impressos, mas a habilidade EF08CO01 exige que o estudante construa soluções recursivas e as automatize em linguagem de programação, o que não ocorre."
    },
    {
      "criterio": "alinhamento_objetivos",
      "nota": 3,
      "justificativa": "Os objetivos OBJ1 e OBJ2 são observáveis, distintos e alinhados ao objetivo geral; descrevem ações que o professor pode observar (identificar, explicar oralmente)."
    },
    {
      "criterio": "coerencia_metodologica",
      "nota": 2,
      "justificativa": "A metodologia descrita (explicação oral, leitura dirigida, discussão) está refletida nas etapas ET1‑ET3, porém a classificação como 'Aula prática' sugere atividade de programação que não está presente, gerando incoerência entre tipo de aula e prática proposta."
    },
    {
      "criterio": "viabilidade",
      "nota": 3,
      "justificativa": "Os recursos (material impresso) e os tempos (15+20+15) são realistas e compatíveis com a duração total de 50 min, não exigindo recursos adicionais."
    },
    {
      "criterio": "avaliacao_aprendizagem",
      "nota": 2,
      "justificativa": "As evidências EVI1 e EVI2 correspondem aos objetivos e os instrumentos INS1 e INS2 coletam as observações, porém os critérios de avaliação são genéricos ('descrever com clareza'), carecendo de rubricas que permitam discriminar desempenho adequado."
    },
    {
      "criterio": "inclusao",
      "nota": 3,
      "justificativa": "As adaptações ADP1 e ADP2 oferecem apoio visual/tátil e suporte oral estruturado, são específicas ao plano e utilizam os mesmos recursos, atendendo ao critério de inclusão."
    }
  ],
  "falhas": [
    {
      "id": "F1",
      "criterio": "aderencia_curricular",
      "componente": "objetivos",
      "gravidade": "maior",
      "descricao": "O plano não inclui a construção de soluções recursivas nem a automação em linguagem de programação, que são requisitos explícitos da habilidade EF08CO01.",
      "correcao_sugerida": "Inserir uma atividade prática em que os estudantes desenvolvam, em papel ou em ambiente digital simples, um algoritmo recursivo (ex.: cálculo de fatorial) e o executem, demonstrando a automatização da solução."
    },
    {
      "id": "F2",
      "criterio": "coerencia_metodologica",
      "componente": "metodologia",
      "gravidade": "maior",
      "descricao": "A aula está rotulada como 'Aula prática', porém as atividades se limitam à leitura e discussão de material impresso, sem prática de programação ou manipulação de código.",
      "correcao_sugerida": "Adequar o tipo de aula ao conteúdo (pode ser 'Aula teórica‑prática') ou incluir, ao final, uma breve prática de codificação de um algoritmo recursivo usando papel ou um ambiente de programação simples."
    },
    {
      "id": "F3",
      "criterio": "avaliacao_aprendizagem",
      "componente": "avaliacao_preliminar",
      "gravidade": "maior",
      "descricao": "O critério de avaliação para o objetivo OBJ2 ('Descrever com clareza oralmente a redução progressiva') é vago e não apresenta rubrica ou indicadores de desempenho que permitam distinguir respostas adequadas de inadequadas.",
      "correcao_sugerida": "Definir uma rubrica com níveis (ex.: 0‑não descreve, 1‑descreve parcialmente, 2‑descreve corretamente) e exemplificar respostas esperadas para orientar a observação do professor."
    }
  ],
  "resumo": "O plano aborda conceitos de recursão de forma observável, mas não cumpre integralmente a habilidade que exige construção e automação de soluções recursivas, apresenta incoerência entre o tipo de aula prática e as atividades propostas e carece de rubricas de avaliação mais precisas."
}

